query:
fetch logs, from: -15d, samplingRatio: 100
| summarize records = count() * takeAny(dt.system.sampling_ratio), content_chars = sum(stringLength(content)) * takeAny(dt.system.sampling_ratio),
    by:{service.name = coalesce(service.name, "unknown"), log.source = coalesce(log.source, "unknown"), loglevel = coalesce(loglevel, "NONE"), day = bin(timestamp, 1d)}

